examples={30:(r'\begin{cases}x+4/x&x<0\\1/x&x>0\end{cases}', 'x=0이 수직점근선, −2까지 증가하고 이후 감소하며 x<0에서 아래로 오목, x>0에서 위로 오목','vertical asymptote0,increasing before−2,decreasing afterward,concave downward for x<0 and upward for x>0',r'f^{\prime}=1-4/x^2\ (x<0),\quad -1/x^2\ (x>0)',r'f^{\prime\prime}=8/x^3\ (x<0),\quad2/x^3\ (x>0)'),31:(r'\begin{cases}2/\pi-\pi x^2/4&x<0\\(2/\pi)\cos(\pi x/2)&0\le x\le4\\2/\pi-\pi(x-4)^2/4&x>4\end{cases}','0,2,4에서 수평접선; 증가 x<0와2<x<4, 감소0<x<2와x>4; 위로 오목1<x<3, 나머지 아래로 오목','horizontal tangents0,2,4;increasing before0 and on(2,4),decreasing on(0,2)and after4;concave upward on(1,3),downward elsewhere',r'f^{\prime}= -\sin(\pi x/2)\quad(0<x<4)',r'f^{\prime\prime}=-(\pi/2)\cos(\pi x/2)\quad(0<x<4)'),32:(r'\begin{cases}-\ln(1-x)&x<1\\\ln(x-1)+(x-1)^2/8&x>1\end{cases}','x=1에 수직점근선, 모든 정의역에서 f′>0, x<1과x>3에서 f″>0,1<x<3에서 f″<0','vertical asymptote1,f′>0 throughout the domain,f″>0 for x<1 or x>3,and f″<0 on(1,3)',r'f^{\prime}=1/(1-x)\ (x<1),\quad1/(x-1)+(x-1)/4\ (x>1)',r'f^{\prime\prime}=1/(1-x)^2\ (x<1),\quad1/4-1/(x-1)^2\ (x>1)'),33:(r'\begin{cases}1-e^{x-2}&x<2\\-(6/\pi)\cos(\pi(x-5)/6)&2\le x\le8\\1-e^{8-x}&x>8\end{cases}','5에서 수평접선인 최소,2와8에서 변곡; 5이전 감소/이후 증가,2–8위로 오목/밖은 아래로 오목','horizontal minimum at5,inflections2 and8;decreasing before5/increasing after5,concave upward on(2,8)/downward outside',r'f^{\prime}=\sin(\pi(x-5)/6)\quad(2<x<8)',r'f^{\prime\prime}=(\pi/6)\cos(\pi(x-5)/6)\quad(2<x<8)'),34:(r'\begin{cases}x+1&x\le-1\\-\ln(2-x)-x/2+\ln3-1/2&-1<x<2\\-\ln(x-2)+(x-2)/2&2<x\le4\\1-\ln2-(x-4)^2&x>4\end{cases}','f′(0)=f′(4)=0, x<−1에서 f′=1; 증가(0,2), 감소(−1,0),(2,4),(4,∞); f′(2−)=∞,f′(2+)=−∞; 위로 오목(−1,2),(2,4), 아래로 오목(4,∞)','f′(0)=f′(4)=0,f′=1 before−1;increasing(0,2),decreasing(−1,0),(2,4),(4,∞);f′(2−)=∞,f′(2+)=−∞;concave upward(−1,2),(2,4),downward after4',r'f^{\prime}=1/(2-x)-1/2\ (-1<x<2),\quad-1/(x-2)+1/2\ (2<x<4)',r'f^{\prime\prime}>0\ (-1<x<2,2<x<4),\quad f^{\prime\prime}=-2\ (x>4)'),35:(r'\begin{cases}(2/\pi)(1-\cos(\pi x/2))&|x|\le6\\4/\pi-(\pi/4)(|x|-6)^2&|x|>6\end{cases}','짝함수이고 f(0)=f′(0)=f′(2)=f′(4)=f′(6)=0; 양의 축에서 증가(0,2),(4,6), 감소(2,4),(6,∞); 위로 오목(0,1),(3,5), 아래로 오목(1,3),(5,∞)','even,f(0)=f′(0)=f′(2)=f′(4)=f′(6)=0;on the positive axis increasing(0,2),(4,6),decreasing(2,4),(6,∞);concave upward(0,1),(3,5),downward(1,3),(5,∞)',r'f^{\prime}=\sin(\pi x/2)\quad(0<x<6)',r'f^{\prime\prime}=(\pi/2)\cos(\pi x/2)\quad(0<x<6)')}
for n,(form,k,e,d1,d2)in examples.items():
 add(n,k+'인 함수의 예를 그려라.','Sketch an example satisfying: '+e+'.',[F('f(x)='+form),F(d1),F(d2),('각 조각의 경계값과 한쪽 도함수를 대조하면 요구된 수평접선·부호·점근선을 확인할 수 있다.','Compare joining values and one-sided derivatives to verify the horizontal tangents,signs,and asymptotes.')],m('f(x)='+form))
add(36,'곡선의 A,B,C,D,E 중 (a)f′,f″ 모두 양수,(b)모두 음수,(c)f′<0,f″>0인 점을 골라라.','Among A,B,C,D,E on the curve,identify(a)both derivatives positive,(b)both negative,(c)f′<0 and f″>0.', [('B는 올라가면서 기울기가 커지고,E는 내려가면서 기울기가 작아지며,A는 내려가면서 기울기가 커진다. C는 증가하지만 아래로 오목하고 D는 수평접선이다.','At B the positive slope increases;at E the negative slope decreases;at A the negative slope increases. C increases but is concave downward;D has a horizontal tangent.')],'(a)B; (b)E; (c)A.',parts=list('abc'))
for n,inc,dec,mx,mn,cu,cd,ip in[(37,'(0,2),(4,6),(8,\infty)','(2,4),(6,8)','2,6','4,8','(3,6),(6,\infty)','(0,3)','3'),(38,'(1,6),(8,\infty)','(0,1),(6,8)','6','1,8','(0,2),(3,5),(7,\infty)','(2,3),(5,7)','2,3,5,7')]:
 add(n,'주어진 연속함수 f의 도함수 그래프에서 (a)증감,(b)극값,(c)오목성,(d)변곡점을 찾고 (e)f(0)=0인 f를 그려라.','From the supplied derivative graph of continuous f,find(a)monotonicity,(b)extrema,(c)concavity,(d)inflections,and(e)sketch f with f(0)=0.',[F(r'\text{Increasing: }'+inc+r';\quad\text{Decreasing: }'+dec),F(r'\text{max: }'+mx+r';\quad\text{min: }'+mn),F(r'\text{CU: }'+cu+r';\quad\text{CD: }'+cd),F(r'\text{Inflections at }x='+ip),('f′의 부호로 f의 증감을, f′의 증감으로 f의 오목성을 정한다. 초기값0에서 누적 면적을 따라 그린다.','Signs of f′ give monotonicity;monotonicity of f′ gives concavity. Sketch accumulated signed area starting from value0.')]+([('6에서는 도함수에 점프가 있어 f는 모서리의 국소최대지만 양쪽 모두 위로 오목이므로 변곡점은 아니다.','At6 the derivative jumps:continuous f has a corner maximum,but is concave upward on both sides,so this is not an inflection.')]if n==37 else[]),m(r'\text{max: }'+mx+r';\ \text{min: }'+mn+r';\ \text{inflection }x='+ip),parts=list('abcde'))
add(53,m(r'f(x)=x^4-cx,\quad c>0')+'의 여러 곡선을 그려 공통점과 차이를 설명하라.','Sketch and compare members of '+m(r'f(x)=x^4-cx,\quad c>0')+'.',[F(r'f^{\prime}=4x^3-c,\quad f^{\prime\prime}=12x^2,\quad a=(c/4)^{1/3}'),F(r'\text{minimum: }(a,-3a^4),\quad\text{zeros: }0,c^{1/3}'),('모두 위로 오목하고 변곡점은 없다. c가 커지면 최솟점은 오른쪽 아래로 이동한다. x=0의 2계 도함수 영점은 오목성을 바꾸지 않는다.','All are concave upward without inflection. As c increases the minimum moves right and down. The zero of f″ at0 does not change concavity.')],'최소(a,−3a⁴), a=(c/4)^(1/3); 변곡점 없음.','Minimum(a,−3a⁴),a=(c/4)^(1/3);no inflection.')
add(54,m(r'f(x)=x^3-3c^2x+2c^3,\quad c>0')+'의 여러 곡선을 비교하라.','Compare members of '+m(r'f(x)=x^3-3c^2x+2c^3,\quad c>0')+'.',[F(r'f=(x-c)^2(x+2c),\quad f^{\prime}=3(x-c)(x+c),\quad f^{\prime\prime}=6x'),F(r'\text{local max: }(-c,4c^3),\quad\text{local min: }(c,0),\quad\text{IP: }(0,2c^3)'),('모두 x<0에서 아래로 오목, x>0에서 위로 오목이다. x=cu로 놓으면 f=c³(u³−3u+2)이므로 같은 모양을 가로 c배, 세로 c³배 한 것이다.','All are concave downward for x<0 and upward for x>0. Substitution x=cu gives f=c³(u³−3u+2):horizontal scale c and vertical scale c³.')],m(r'\text{max: }(-c,4c^3);\ \text{min: }(c,0);\ \text{IP: }(0,2c^3)'))
a=(3-s.sqrt(17))/4;z=(3+s.sqrt(17))/4
add(55,m(r'f(x)={x+1\over\sqrt{x^2+1}}')+'의 (a)최대·최솟값,(b)가장 빨리 증가하는 x를 그래프에서 추정하고 정확히 구하라.','For '+m(r'f(x)={x+1\over\sqrt{x^2+1}}')+',estimate then compute(a)extreme values and(b)where it increases fastest.',[F(r'f^{\prime}={1-x\over(x^2+1)^{3/2}},\quad f^{\prime\prime}={2x^2-3x-1\over(x^2+1)^{5/2}}'),('x=1에서 증가에서 감소로 바뀌므로 최댓값 √2≈1.414이다. x→−∞에서 −1에 접근하지만 도달하지 않으므로 최솟값은 없다.','At1 the function changes from increasing to decreasing,giving maximum√2≈1.414. It approaches−1 as x→−∞ without attaining it,so no minimum exists.'),F(r'f^{\prime\prime}=0\iff x=(3\pm\sqrt{17})/4'),('작은 근에서 f′가 증가에서 감소로 바뀌고 큰 근은 f′의 최소점이다. 양끝에서 f′→0이므로 전역 최대 기울기는 작은 근에서 생긴다.','The smaller root is a maximum of f′;the larger is a minimum. Since f′→0 at both infinities,the global maximum slope occurs at the smaller root.')],m(r'\max f=\sqrt2;\quad x_{\rm fastest}={3-\sqrt{17}\over4}\approx-0.281')+'; 최솟값 없음.',m(r'\max f=\sqrt2;\quad x_{\rm fastest}={3-\sqrt{17}\over4}\approx-0.281')+';no minimum.',list('ab'))
add(56,m(r'f(x)=x+2\cos x,\quad0\le x\le2\pi')+'의 (a)극값,(b)가장 빨리 증가하는 x를 추정하고 정확히 구하라.','For '+m(r'f(x)=x+2\cos x,\quad0\le x\le2\pi')+',estimate then compute(a)extrema and(b)where the function increases fastest.',[F(r'f^{\prime}=1-2\sin x=0\iff x=\pi/6,5\pi/6'),F(r'f(0)=2,\ f(\pi/6)=\pi/6+\sqrt3,\ f(5\pi/6)=5\pi/6-\sqrt3,\ f(2\pi)=2\pi+2'),('국소최대는 π/6에서 약2.256, 국소최소는5π/6에서 약0.886이다. 끝점까지 비교하면 절대최대는2π+2≈8.283, 절대최소는5π/6−√3이다.','The local maximum atπ/6 is about2.256;the local minimum at5π/6 is about0.886. Endpoint comparison gives absolute maximum2π+2≈8.283 and absolute minimum5π/6−√3.'),F(r'\max f^{\prime}=3\quad\text{at }x=3\pi/2\approx4.712')],m(r'\min f=5\pi/6-\sqrt3;\quad\max f=2\pi+2;\quad x_{\rm fastest}=3\pi/2'),parts=list('ab'))
# Numerical concavity estimates are backed by complete real polynomial roots.
for n,f,roots,lo,hi,exclude in[(57,s.sin(2*x)+s.sin(4*x),[s.acos(-R(1,8))/2,s.pi/2,s.pi-s.acos(-R(1,8))/2],0,s.pi,[]),(58,(x-1)**2*(x+1)**3,[-1,(1-s.sqrt(6))/5,(1+s.sqrt(6))/5],-s.oo,s.oo,[]),(59,(x**4+x**3+1)/s.sqrt(x*x+x+1),None,-s.oo,s.oo,[]),(60,(x+1)**3*(x*x+5)/((x**3+1)*(x*x+4)),None,-s.oo,s.oo,[-1])]:
 dd=s.factor(s.diff(f,x,2));num=s.fraction(dd)[0]
 if roots is None:roots=[s.Float(s.re(v),16)for v in s.nroots(num,maxsteps=500)if abs(float(s.im(v)))<1e-10]
 cuts=sorted(set(roots+exclude),key=float);ends=[lo]+cuts+[hi];sg=[1 if realval(dd,test(a,z))>0 else-1 for a,z in zip(ends,ends[1:])];steps=[F(r'f^{\prime\prime}(x)='+tx(dd))];res=[]
 for sign,k,e in[(1,'위로 오목','Concave upward'),(-1,'아래로 오목','Concave downward')]:
  def fmt(v):return tx(v)if v in[-s.oo,s.oo]else f'{float(v):.3f}'
  st=m(r'\cup'.join('('+fmt(a)+','+fmt(z)+')'for a,z,q in zip(ends,ends[1:],sg)if q==sign)or r'\varnothing');steps.append((k+': '+st,e+': '+st));res.append((k+': '+st,e+': '+st))
 if n<=58:
  pts=m(',\;'.join('('+f'{float(c):.4f}'+','+f'{realval(f,c):.4f}'+')'for c in roots));steps.append(('변곡점 근사: '+pts,'Approximate inflection points: '+pts));res.append(('변곡점: '+pts,'Inflection points: '+pts))
 if n>=59:
  rounded=m(', '.join(f'{float(c):.1f}' for c in roots));steps.append(('소수 첫째 자리의 경계: '+rounded,'Boundaries rounded to one decimal: '+rounded));res.append(('경계(소수 첫째 자리): '+rounded,'Boundaries(one decimal): '+rounded))
 if n==60:steps.append(('x=−1은 약분해도 원래 정의역에서 제외된 제거 가능 불연속점이다. 변곡점으로 세지 않는다.','Cancellation does not restore x=−1 to the original domain. This removable discontinuity is not an inflection point.'))
 steps.append(('함수 그래프의 추정보다 2계 도함수의 부호 변화가 정확한 경계를 준다. 표시된 소수 경계는 근삿값이다.','Second derivative sign changes refine the function-graph estimate. Decimal boundaries are approximate.'))
 add(n,m('f(x)='+tx(f))+'의 그래프와 f″ 그래프로 오목성 및 변곡점을 추정하라.'if n<=58 else m('f(x)='+tx(f))+'의 f″를 계산해 오목 구간 경계를 소수 첫째 자리까지 추정하라.','Use graphs of '+m('f(x)='+tx(f))+' and f″ to estimate concavity and inflection points.'if n<=58 else'Compute and graph f″ for '+m('f(x)='+tx(f))+' to estimate concavity boundaries to one decimal place.',steps,'; '.join(k for k,e in res),'; '.join(e for k,e in res),list('ab')if n<=58 else[])
 checks.append({'exercise':n,'inflectionCandidates':[float(c)for c in roots],'method':'Complete polynomial real-root count for algebraic numerators; exact trigonometric factorization for57.'})
add(61,'효모 개체수 그래프에서 (a)증가율의 변화,(b)최대 증가율 시각,(c)오목 구간,(d)변곡점을 추정하라.','From the yeast population graph,estimate(a)how growth rate changes,(b)when it is highest,(c)concavity intervals,and(d)the inflection point.', [('초기에는 기울기가 점점 커지고 약8시간 이후에는 작아진다. 개체수 자체는 계속 증가한다.','The slope increases initially and decreases after about8 hours;population itself continues increasing.'),('최대 증가율은 약8시간, 위로 오목은(0,8), 아래로 오목은(8,18)이다. 변곡점은 대략(8,350)이다.','The largest growth rate is around8 hours. Concavity is upward on(0,8),downward on(8,18),with approximate inflection(8,350).')],'약8시간에서 최대 증가율, 변곡점≈(8,350).','Maximum growth rate near8 hours;inflection≈(8,350).',list('abcd'))
add(62,'시험 점수가 계속 하락하지만 하락 속도는 느려진다는 말을 함수와 도함수로 해석하라.','Interpret a score that is declining at a slowing rate using derivatives.', [('점수를 S(t)라 하면 내려가므로 S′<0이다. 음의 기울기가 0에 가까워지므로 S′는 증가하고 S″>0이다.','For score S(t),decline means S′<0. The negative slope becomes less negative,so S′ increases and S″>0.')],m(r'S^{\prime}<0,\quad S^{\prime\prime}>0'))
add(63,'재정 적자가 증가하지만 증가 속도는 줄어든다는 말을 도함수로 해석하라.','Interpret a deficit increasing at a decreasing rate using derivatives.', [('적자를 D(t)라 하면 값은 증가하므로 D′>0이고 양의 기울기가 작아지므로 D″<0이다.','For deficit D(t),the value increases so D′>0,but its positive slope falls,so D″<0.')],m(r'D^{\prime}>0,\quad D^{\prime\prime}<0'))
add(64,'t=3에 덥다고 느낀다. 기온의 (f′(3),f″(3))이 (a)(2,4),(b)(2,−4),(c)(−2,4),(d)(−2,−4)일 때 해석하라.','You feel hot at t=3.Interpret temperature derivatives(a)(2,4),(b)(2,−4),(c)(−2,4),(d)(−2,−4).',[('(a)더워지며 상승이 가속된다. (b)더워지지만 상승은 둔화된다.','(a)Warming accelerates.(b)Warming continues but slows.'),('(c)식고 있지만 냉각이 둔화된다. (d)식으며 냉각이 가속된다.','(c)Cooling slows.(d)Cooling accelerates.'),('이 정보는 그 순간의 변화 경향만 말하며 장시간 뒤 기온이나 변화 방향의 역전을 보장하지 않는다.','These are instantaneous trends;they do not guarantee a later temperature or reversal.')],'(a)더 불편해짐; (b)상승 둔화; (c)냉각 둔화; (d)빠르게 식음.','(a)Accelerating warming;(b)slowing warming;(c)slowing cooling;(d)accelerating cooling.',list('abcd'))
add(65,'공부시간 t의 지식량 K(t)에 대해 K(8)−K(7)과 K(3)−K(2)를 비교하고 오목성을 논하라.','Compare K(8)−K(7) with K(3)−K(2) for knowledge gained after t study hours,and discuss concavity.', [('피로와 한계 학습효과 감소를 가정하면 늦은 한 시간의 증가량이 작다.','Assuming fatigue and diminishing learning returns,the later hour yields less.'),F(r'K(8)-K(7)<K(3)-K(2)'),('이 모형에서는 K′가 감소하여 아래로 오목하다. 학습 과정의 경험적 가정이며 모든 사람에게 성립하는 수학적 사실은 아니다.','In this model K′ decreases,so K is concave downward. This is an empirical modeling assumption,not a universal mathematical fact.')],'학습효과 감소 모형에서는 이른 한 시간의 증가가 크고 K는 아래로 오목하다.','With diminishing returns,the earlier gain is larger and K is concave downward.')
add(66,'가운데가 좁은 컵에 일정한 부피 유량으로 커피를 부을 때 깊이 h(t)의 그래프와 변곡점 의미를 설명하라.','Coffee enters a narrow-waisted mug at constant volume rate.Sketch depth h(t)and interpret its inflection.',[F(r'A(h)h^{\prime}(t)=Q>0,\qquad h^{\prime\prime}(t)=-{Q^2 A^{\prime}(h)\over A(h)^3}'),('아래쪽에서 컵이 좁아지는 동안 단면적 A가 줄어 깊이 증가가 빨라지고 위로 오목하다. 허리를 지난 뒤에는 넓어져 증가가 느려지고 아래로 오목하다.','As the lower part narrows,area A decreases and depth rises faster:concave upward. Above the waist the mug widens and the rise slows:concave downward.'),('변곡점은 물높이가 가장 좁은 단면에 도달한 순간이며 깊이 증가율이 가장 크다.','The inflection occurs when the surface reaches the narrowest cross-section,where depth rises fastest.')],'증가하는 S자 곡선; 가장 좁은 높이를 지날 때 변곡.','An increasing S-curve,inflecting at the narrowest height.')
add(67,'x=−2에서 국소최댓값3, x=1에서 국소최솟값0을 갖는 삼차함수를 구하라.','Find a cubic with local maximum3 at x=−2 and local minimum0 at x=1.',[F(r'f^{\prime}(x)=k(x+2)(x-1)'),F(r'f(x)=k(x^3/3+x^2/2-2x)+d'),F(r'f(-2)-f(1)=9k/2=3\Longrightarrow k=2/3,\quad d=7/9'),F(r'f^{\prime\prime}(x)=(4x+2)/3'),('−2에서 2계 도함수는 음수이고 1에서는 양수이다.','The second derivative is negative at−2 and positive at1.')],m(r'f(x)={2x^3+3x^2-12x+7\over9}'))
add(68,m(r'y={1+x\over1+x^2}')+'의 변곡점 세 개가 한 직선 위에 있음을 보여라.','Show the three inflection points of '+m(r'y={1+x\over1+x^2}')+' are collinear.',[F(r'y^{\prime\prime}={2(x-1)(x^2+4x+1)\over(1+x^2)^3}'),F(r'x=1,-2-\sqrt3,-2+\sqrt3'),('세 단순근에서 모두 부호가 바뀐다. 각 근을 원래 함수와 직선에 대입한다.','All three simple roots change sign.Substitute them into the original function and the line.'),F(r'y={x+3\over4}')],m(r'x=1,-2\pm\sqrt3;\quad y=(x+3)/4'))
add(69,m(r'y=x\sin x')+'의 모든 변곡점이 '+m(r'y^2(x^2+4)=4x^2')+' 위에 있음을 증명하라.','Show every inflection point of '+m(r'y=x\sin x')+' lies on '+m(r'y^2(x^2+4)=4x^2')+'.',[F(r'y^{\prime\prime}=2\cos x-x\sin x=0\Longrightarrow y=2\cos x'),F(r'y^2=x^2\sin^2x=x^2(1-y^2/4)'),('정리하면 주장한 식이다. 이는 변곡점의 필요조건을 사용한 포함관계이며 역을 주장하지 않는다.','Rearrangement gives the stated equation.This is containment using a necessary condition,not a claim of the converse.')],m(r'y^2(x^2+4)=4x^2'))
add(70,'2계 도함수가 0이 아닌 함수에 대해 (a)위로 오목한 f,g의 합, (b)양수이고 위로 오목한 f의 제곱도 위로 오목임을 증명하라.','For nonzero second derivatives,prove upward concavity of(a)the sum of two concave-up functions and(b)the square of a positive concave-up function.',[F(r'(f+g)^{\prime\prime}=f^{\prime\prime}+g^{\prime\prime}>0'),F(r'(f^2)^{\prime\prime}=2(f^{\prime})^2+2ff^{\prime\prime}>0')],'두 경우 모두 2계 도함수가 양수이다.','Both second derivatives are positive.',list('ab'))
add(71,'양수이고 위로 오목한 f,g가 (a)둘 다 증가,(b)둘 다 감소하면 곱도 위로 오목임을 보이고, (c)반대 방향 증감일 때 세 가지 오목성의 예를 제시하라.','For positive concave-up f,g,prove the product is concave up when(a)both increase or(b)both decrease;give(c)three outcomes for opposite monotonicity.',[F(r'(fg)^{\prime\prime}=f^{\prime\prime}g+2f^{\prime}g^{\prime}+fg^{\prime\prime}'),('(a)(b)에서는 가운데 항도 음수가 아니고 다른 두 항은 양수이다. (c)에서는 가운데 항이 음수라 결론이 정해지지 않는다.','In(a)(b)the middle term is nonnegative and the other two positive. In(c)the middle term is negative,so the conclusion is undetermined.'),F(r'I=(2,3):\quad f=e^{2x},g=e^{-x}\Longrightarrow fg=e^x\quad(\mathrm{CU})'),F(r'f=e^x,g=(10-x^2)e^{-x}\Longrightarrow fg=10-x^2\quad(\mathrm{CD})'),F(r'f=e^x,g=xe^{-x}\Longrightarrow fg=x\quad(\mathrm{linear})'),('각 예에서 I 위의 두 함수는 양수·위로 오목이고 f는 증가, g는 감소한다.','In each example,both factors are positive and concave upward on I,f increases,and g decreases.')],'반대 증감에서는 곱이 위로 오목·아래로 오목·직선 모두 가능하다.','Opposite monotonicity permits upward concavity,downward concavity,or a line.',list('abc'))
add(72,'실수 전체에서 위로 오목한 f,g에 대해 f∘g도 위로 오목이 되도록 하는 f의 조건을 제시하라.','Give a condition on f ensuring that f∘g is concave upward when f,g are concave upward on the real line.',[F(r'(f\circ g)^{\prime\prime}=f^{\prime\prime}(g)(g^{\prime})^2+f^{\prime}(g)g^{\prime\prime}'),('f가 증가하여 g의 치역에서 f′>0이면 두 번째 항은 양수이고 첫 번째는 음수가 아니므로 충분하다.','It suffices that f′>0 on the range of g:the second term is positive and the first nonnegative.')],'충분조건: f가 증가함, 특히 g의 치역에서 f′>0.','Sufficient: f is increasing,with f′>0 on the range of g.')
add(73,'삼차함수는 변곡점이 정확히 하나임을 보이고 세 실근이 있을 때 변곡점 x좌표가 근의 평균임을 증명하라.','Show a cubic has exactly one inflection point and,when it has three real roots,its abscissa is their average.',[F(r'f=ax^3+bx^2+cx+d,\ a\ne0,\qquad f^{\prime\prime}=6ax+2b'),('이 일차식의 유일한 영점에서 부호가 반드시 바뀐다.','This linear expression changes sign at its unique zero.'),F(r'x_{\rm IP}=-{b\over3a},\qquad x_1+x_2+x_3=-b/a')],m(r'x_{\rm IP}=(x_1+x_2+x_3)/3'))
add(74,m(r'P(x)=x^4+cx^3+x^2')+'가 변곡점2개,1개,0개를 가질 c를 구하고 c 변화에 따른 그래프를 비교하라.','Classify c for two,one,or zero inflections of '+m(r'P(x)=x^4+cx^3+x^2')+' and compare graphs as c varies.',[F(r'P^{\prime\prime}=12x^2+6cx+2,\quad\Delta=36c^2-96'),('판별식이 양수이면 두 단순근에서 부호가 바뀐다. 0이면 중근에 닿기만 하므로 변곡점이 아니다. 음수이면 항상 위로 오목이다.','Positive discriminant gives two sign-changing simple roots. Zero discriminant gives a double zero with no sign change;negative discriminant gives upward concavity everywhere.'),F(r'|c|>\sqrt{8/3}:2;\quad |c|\le\sqrt{8/3}:0'),('변곡점1개인 경우는 없다. c가 감소하면 x>0의 높이는 낮아지고 x<0의 높이는 높아진다. c와−c 그래프는 y축 대칭이다.','Exactly one inflection is impossible. Decreasing c lowers the graph for x>0 and raises it for x<0. Parameters c and−c give reflection across the y-axis.')],m(r'2\iff |c|>\sqrt{8/3};\quad0\iff |c|\le\sqrt{8/3};\quad1:\text{ impossible}'))
add(75,'변곡점 c 주변 열린 구간에 f″가 존재하면 f″(c)=0임을 증명하라.','If f″ exists on an open interval containing an inflection c,prove f″(c)=0.', [('오목성 변화에 의해 g=f′는 c의 한쪽에서는 증가하고 다른 쪽에서는 감소하거나 반대이다. 따라서 g는 c에서 국소 극값을 가진다.','The concavity change makes g=f′ increase on one side of c and decrease on the other,or conversely.Thus g has a local extremum at c.'),('g가 c에서 미분 가능하므로 페르마 정리에 의해 g′(c)=0이다.','Since g is differentiable at c,Fermat’s theorem gives g′(c)=0.')],m(r'f^{\prime\prime}(c)=g^{\prime}(c)=0'))
add(76,'f(x)=x⁴에서 f″(0)=0이지만 0은 변곡점이 아님을 보여라.','Show f(x)=x⁴ has f″(0)=0 but no inflection at0.',[F(r'f^{\prime\prime}(x)=12x^2\ge0'),('0의 양쪽 모두 위로 오목하므로 오목성 변화가 없다.','The curve is concave upward on both sides,with no concavity change.')],'변곡점 아님.','Not an inflection point.')
add(77,'g(x)=x|x|의 (0,0)은 변곡점이지만 g″(0)이 없음을 보여라.','Show g(x)=x|x| has an inflection at(0,0)but no g″(0).',[F(r'g(x)=\begin{cases}-x^2&x<0\\x^2&x\ge0\end{cases},\quad g^{\prime}(x)=2|x|'),F(r'g^{\prime\prime}=-2\ (x<0),\quad2\ (x>0)'),('g는 연속이고 오목성은 바뀌지만 g′의 좌우 기울기가 달라 0에서 2계 도함수는 없다.','The continuous curve changes concavity,but unequal one-sided slopes of g′ prevent a second derivative at0.')],'변곡점(0,0); g″(0) 미정의.','Inflection(0,0);g″(0)undefined.')
add(78,'f‴가 연속이고 f′(c)=f″(c)=0,f‴(c)>0이면 c에서 극값·변곡점이 있는지 판단하라.','If f‴ is continuous,f′(c)=f″(c)=0,and f‴(c)>0,determine extrema and inflection at c.', [('가까운 근방에서 f‴>0이므로 f″는 증가하며 c 왼쪽에서 음수, 오른쪽에서 양수이다. 따라서 변곡점이다.','Near c,f‴>0 makes f″ increase through0,negative to the left and positive to the right.Thus c is an inflection.'),('f′는 c에서 값0인 국소최소이다. 양쪽에서 f′>0이므로 f는 양쪽 모두 증가하며 극값은 없다.','The derivative f′ has local minimum0 at c,so f′>0 on both sides.Thus f increases on both sides and has no extremum.')],'수평접선인 변곡점이며 극값은 아니다.','A stationary inflection,not an extremum.')
add(79,'미분 가능한 f가 구간 I에서 한 점 c를 제외하고 f′>0이면 I 전체에서 증가함을 증명하라.','Prove f is increasing on I if it is differentiable and f′>0 except possibly at one point c.', [('c의 각 한쪽에서는 평균값 정리로 엄격히 증가한다. c를 끝점으로 하는 구간에도 평균값 정리를 적용하면 도함수를 평가하는 점은 내부에 있어 c와 다르므로 엄격한 부등식을 얻는다.','The MVT gives strict increase on each side. For an interval ending at c,the MVT evaluation point is interior and therefore differs from c,again giving strict inequality.'),('x₁<c<x₂이면 f(x₁)<f(c)<f(x₂)를 이어 붙인다.','For x₁<c<x₂,combine f(x₁)<f(c)<f(x₂).')],'I 전체에서 엄격히 증가한다.','Strictly increasing throughout I.')
add(80,m(r'f(x)=cx+{1\over x^2+3}')+'가 실수 전체에서 증가할 c의 범위를 구하라.','Find all c for which '+m(r'f(x)=cx+{1\over x^2+3}')+' is increasing on the real line.',[F(r'f^{\prime}=c-q(x),\quad q(x)={2x\over(x^2+3)^2},\quad q^{\prime}(x)={6(1-x^2)\over(x^2+3)^3}'),F(r'\max q=q(1)=1/8'),('c>1/8이면 f′>0이다. c=1/8이면 x=1에서만 0이고 나머지에서 양수여서 앞 문제에 의해 엄격히 증가한다. 더 작으면 1 주변에서 도함수가 음수이다.','For c>1/8,f′>0. At equality it vanishes only at1 and is otherwise positive,so the preceding result gives strict increase. Smaller c makes the derivative negative near1.')],m(r'c\ge1/8'))
add(81,'0에서 값0이고 x≠0에서 f=x⁴sin(1/x),g=x⁴(2+sin(1/x)),h=x⁴(−2+sin(1/x))이다. (a)0이 임계수이고 양쪽에서 도함수 부호가 무한히 바뀜을 보이고 (b)극값을 분류하라.','Define value0 at0 and,for x≠0,f=x⁴sin(1/x),g=x⁴(2+sin(1/x)),h=x⁴(−2+sin(1/x)).Prove(a)criticality and infinitely oscillating derivative signs on both sides,and(b)classify extrema at0.',[F(r'F_A(x)=x^4(A+\sin(1/x)),\quad A=0,2,-2'),F(r'F_A^{\prime}(0)=\lim_{x\to0}x^3(A+\sin(1/x))=0'),F(r'F_A^{\prime}(x)=4x^3(A+\sin(1/x))-x^2\cos(1/x)'),('x=±1/(2πn)에서는 −x² 항이 지배하여 음수이고 x=±1/((2n+1)π)에서는 +x² 항이 지배하여 양수이다. 충분히 큰 n에 대해 성립하므로 양쪽 모두 무한히 부호가 바뀐다.','At x=±1/(2πn),the dominant term is−x²;at x=±1/((2n+1)π),it is+x². This holds for all sufficiently large n,on both sides.'),('f는 0 근처에서 양수·음수 값을 모두 취한다. g는 x≠0에서 x⁴ 이상으로 양수이고 h는 −x⁴ 이하로 음수이다.','Near0,f takes both signs. For x≠0,g≥x⁴>0 and h≤−x⁴<0.')],'f:극값 없음; g:엄격한 국소최소; h:엄격한 국소최대.','f:neither;g:strict local minimum;h:strict local maximum.',list('ab'))
assert sorted(b.E)==list(range(1,82)),sorted(set(range(1,82))-set(b.E))
def norm(v):
 if isinstance(v,str):
  chunks=re.split(r'(\\\(.*?\\\)|\\\[.*?\\\])',v,flags=re.S)
  return ''.join(z if i%2 else z.replace('<',r'\(\lt\)')for i,z in enumerate(chunks))
 if isinstance(v,list):return[norm(z)for z in v]
 if isinstance(v,dict):return{k:norm(z)for k,z in v.items()}
 return v
b.E=norm(b.E);b.save()
